    }
};

class ConfigUpdater {
private:
    InterfaceTable& interfaceTable;
    tcp::socket socket;
    boost::asio::steady_timer timer;
    int updateFrequencySeconds;

    void DoWork() {
        // Implement resilient retry mechanism for failed API calls
        while (true) {
            try {
                // Fetch configuration updates from the external REST API
                // ...

                break; // Successful request, no need to retry
            } catch (exception& e) {
                // Log error information and wait before retrying
                cout << "Error: " << e.what() << endl;
                this_thread::sleep_for(chrono::seconds(5));
            }
        }
