        : interfaceTable(interfaceTable), timer(io_service), updateFrequencySeconds(updateFrequencySeconds) {
        timer.expires_from_now(chrono::seconds(updateFrequencySeconds));
        timer.async_wait([this](boost::system::error_code ec) { if (!ec) DoWork(); });
