public class CustomUserValidator : IUserValidator<ApplicationUser>
{
    private readonly IUsernameReservationService _usernameReservationService;

    public CustomUserValidator(IUsernameReservationService usernameReservationService)
    {
        _usernameReservationService = usernameReservationService;
    }

    public async Task<IdentityResult> ValidateAsync(ApplicationUser user)
    {
        var result = new IdentityResult();

        if (await _usernameReservationService.IsReservedOrBlacklisted(user.UserName))
        {
            result.AddError(new IdentityError
            {
                Code = "UsernameInvalid",
                Description = "This username is reserved or blacklisted."
            });
        }

        if (await _usernameReservationService.CheckPasswordComplexity(user.Password))
        {
            result.AddError(new IdentityError
            {
                Code = "PasswordInvalid",
                Description = "This password does not meet the required complexity."
            });
        }

        return result;
    }
}
