    persistent: true,
    ignoreInitial: false,
    depth: 1
  });

  watcher.on('add', (filePath) => {
    if (activeTasksCount < maxConcurrentTasks) {
      activeTasksCount++;
      processFile(filePath, outputDir).finally(() => {
        activeTasksCount--;
      });
    }
  });
};

