const loadModule = (moduleName) => {
  // Load the module using require
  const promises = [];

  // If the module has dependencies, add them to the promises array
  if (moduleName.dependencies && Object.keys(moduleName.dependencies).length > 0) {
    promises.push(...Object.entries(moduleName.dependencies).map(([dep, mod]) => loadModule(mod).then(m => m.require(dep))));
  }

  // Add a promise for loading the module itself
  promises.push(Bluebird.promisify(require)(moduleName.main).catch((err) => {
    errorLog(err);
    throw err;
  }));

  return Bluebird.all(promises).then((modules) => modules[0]);
};

// Function to mock and execute test functions in an isolated environment
const runTests = (module, testSuiteLabel) => {
  const blueslipMocker = new Blueslip();

  // Execute each test function within an isolated environment using Blueslip
  return asyncMap(module.tests, (test) => {
    // Reset Blueslip for each test to avoid side effects between tests
    blueslipMocker.reset();

    // Add mock dependencies as needed
    if (test.dependencies && Object.keys(test.dependencies).length > 0) {
      blueslipMocker.mock(...Object.entries(test.dependencies).map(([dep, fn]) => [dep, fn]));
    }

    // If the test requires shared state across tests, store it in Blueslip's context
    if (test.sharedState) {
      blueslipMocker.context(test.sharedState);
    }

    try {
      log(`Running test: ${chalk.green(test.name)} (${testSuiteLabel})`);
      return await test.function();
    } catch (err) {
      log(`Test ${chalk.red(test.name)} (${testSuiteLabel}) failed. Error: ${err.message}`);
      errorLog(err);
      throw err;
    }
  });
};

// The main runModuleTests function
const runModuleTests = (moduleName, options) => {
  return loadModule(moduleName).then((module) => {
    const startTime = new Date();

    // Execute the tests and gather results
    return runTests(module, moduleName).then((results) => {
      const endTime = new Date();
      const elapsedTime = endTime - startTime;

      log(`Test suite ${chalk.green(moduleName)} completed in ${elapsedTime}ms`);

      // Summarize the results and return them
