#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <jansson.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <time.h>

// Custom error codes and messages
enum ErrorCode {
    SUCCESS = 0,
    SERVICE_UNAVAILABLE = -1,
    NETWORK_ERROR = -2,
    DATA_CORRUPTED = -3,
    INSUFFICIENT_MEMORY = -4,
    INTERNAL_ERROR = -5
};

char* loadResourceBundle(const char* resourceId) {
    static sem_t mutex = SEM_INITIALIZER_UNLOCKED; // Global lock for thread safety
    static pthread_key_t threadDataKey; // Per-thread data storage

    pthread_key_t_init(&threadDataKey, NULL);

    void* threadData;
    ResourceBundleInfo* resourceBundleInfo = (ResourceBundleInfo*)pthread_getspecific(threadDataKey);

    if (!resourceBundleInfo) { // If no data available in the per-thread storage
        resourceBundleInfo = malloc(sizeof(ResourceBundleInfo));
        pthread_setspecific(threadDataKey, resourceBundleInfo);
    }

    sem_wait(&mutex);

    time_t lastFetchTime[MAX_RESOURCES];
    ResourceBundle* resourceBundles[MAX_RESOURCES] = { NULL };

    size_t index = hash(resourceId) % MAX_RESOURCES; // Calculate index for cache mapping

    if (lastFetchTime[index] + CACHE_TTL > time(NULL)) { // If the resource was fetched recently, use the cached data
        ResourceBundle* bundle = resourceBundles[index];
        sem_post(&mutex);

        if (!bundle->data) { // Check if the bundle is completely loaded
            return createErrorMessage(DATA_CORRUPTED);
        }

        return json_string_dup(json_object_get(bundle->obj, resourceId));
    }

    lastFetchTime[index] = time(NULL); // Update the cache fetch timestamp

    if (!resourceBundles[index]) { // If no bundle for this index, create a new one
        ResourceBundle* bundle = mmap(NULL, BUNDLE_CHUNK_SIZE, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        resourceBundles[index] = bundle;
    }

    size_t bytesRead = fetchResourceBundle(resourceId, resourceBundles[index], BUNDLE_CHUNK_SIZE);

    if (bytesRead == 0) { // If no data was received, indicate an error and return
        sem_post(&mutex);
        return createErrorMessage(NETWORK_ERROR);
    }

    ResourceBundleInfo* bundleInfo = resourceBundleInfo + index;
    bundleInfo->loadedBytes += bytesRead;
    bundleInfo->totalBytes += bytesRead;

    if (bundleInfo->loadedBytes >= bundleInfo->totalBytes) { // If the entire bundle is loaded, mark it as complete
        json_t* obj = json_loads(resourceBundles[index], 0, NULL);
        resourceBundles[index]->obj = obj;
    }

    sem_post(&mutex);

    return json_string_dup(json_object_get(resourceBundles[index]->obj, resourceId));
}

// Other helper functions for caching, error handling, and chunked data transfer go here.
```

