2. **Filtering Based on Class and ID Selectors**: Implement recursive depth-first search traversal of the DOM tree using a utility function that accepts a callback filter function. The filter function should check for class or id selectors.

```javascript
function traverse(node, cb) {
  if (node) {
    const nodesToProcess = [node];

    while (nodesToProcess.length > 0) {
      const currentNode = nodesToProcess.pop();

      cb(currentNode);

      for (const child of currentNode.children) {
        nodesToProcess.push(child);
      }

      // Traverse siblings recursively
      let sibling = currentNode.nextSibling;
      while (sibling && sibling !== currentNode) {
        nodesToProcess.push(sibling);
        sibling = sibling.nextSibling;
      }
    }
  }
}
```

