```javascript
import { fileURLToPath, URL } from 'url';
import { dirname } from 'path';
import { promises as fs } from 'fs';
import chalk from 'chalk';
import { createRequire } from 'module';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const rootDir = __dirname;

async function loadModule(moduleName, moduleType) {
  const modulePath = getModulePath(moduleName, moduleType);

  try {
    if (moduleType === 'commonjs') {
      return require.resolveSync(modulePath);
    } else if (moduleType === 'esm') {
      return await import(modulePath);
    }
  } catch (error) {
    console.log(`${chalk.redBright} Error loading module "${moduleName}":`, error.message);
    return null;
  }
}

function getModulePath(moduleName, moduleType) {
  const moduleExtensions = ['.js', '.json'];

  for (const extension of moduleExtensions) {
    const candidatePath = path.join(rootDir, `${moduleName}${extension}`);

    if (fs.existsSync(candidatePath)) {
      return candidatePath;
    }
  }

  throw new Error(`Module "${moduleName}" not found in specified directory`);
}

// Main application logic
async function main() {
  const moduleToLoad = 'your-target-module';
  const moduleType = 'esm'; // or 'commonjs' based on your needs

  const loadedModule = await loadModule(moduleToLoad, moduleType);

  if (loadedModule) {
    // Call the loaded module's default export function (if available)
    const moduleFunction = loadedModule.default || loadedModule;
    moduleFunction();
  }
}

main();
```

