use Illuminate\Queue\InteractsWithQueue;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Foundation\Bus\Dispatchable;

class PasswordUpdater implements ShouldQueue, InteractsWithQueue
{
    use Dispatchable;

    protected $userID, $newPassword, $authHeaders;
    protected $authServiceURL, $notificationQueue;
    protected $rateLimiter, $securityPolicy;

    public function __construct($userID, $newPassword, $authHeaders, $authServiceURL, $notificationQueue, $rateLimiter, $securityPolicy)
    {
        $this->userID = $userID;
        $this->newPassword = $newPassword;
        $this->authHeaders = $authHeaders;
        $this->authServiceURL = $authServiceURL;
        $this->notificationQueue = $notificationQueue;
        $this->rateLimiter = $rateLimiter;
        $this->securityPolicy = $securityPolicy;
    }

    public function handle()
    {
        if (!$this->isValidPassword($this->newPassword)) {
            throw new \InvalidArgumentException('Provided password does not meet security requirements.');
        }

        try {
            $this->rateLimiter->limit();
            $response = (new Client())->put(
                $this->authServiceURL . '/users/' . $this->userID,
                [
                    'headers' => $this->authHeaders,
                    'json' => ['password' => $this->newPassword]
                ]
            );

            if ($response->getStatusCode() !== 200) {
                throw new \Exception('Failed to update user password.');
            }
        } catch (GuzzleException $e) {
            if (!$e->hasResponse()) {
                // Transient network failure, retry after a short delay.
                sleep(5);
                return $this->handle();
            }

            throw new \Exception('Failed to update user password.');
        }

        $this->notificationQueue->push(new PasswordChangeNotification($this->userID));

        Log::info('Password changed for user ' . $this->userID);

        return true;
    }

    protected function isValidPassword($password)
    {
