#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <sys/types.h>
#include <fcntl.h>
#include <dirent.h>
#include <iostream>
#include <vector>
#include <map>
#include <functional>

// Logging framework interface (abstract)
class ILogger {
public:
    virtual void log(const char* message) = 0;
};

// SHA-256 hashing utility function
std::string sha256(const uint8_t* data, size_t length) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, data, length);
    SHA256_Final(digest, &ctx);

    std::string result;
    for (unsigned int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        result += std::hex << static_cast<int>(digest[i]);
    }

    return result;
}

// Log utility class
class LogUtil {
private:
    ILogger& logger;
    const char* log_dir;
    pthread_mutex_t lock;

public:
    LogUtil(ILogger& logger_, const char* log_dir_) : logger(logger_), log_dir(log_dir_), lock(PTHREAD_MUTEX_INITIALIZER) {}

    // Asynchronously logs a message with a unique filename based on content, timestamp, and environment variables.
    void asyncLog(const char* message) {
        pthread_t tid;
        pthread_create(&tid, nullptr, [this, message]() {
            this->logImpl(message);
            return 0;
        });
    }

    // Implementation detail for asynchronous logging, called from worker threads.
    void logImpl(const char* message) {
        pthread_mutex_lock(&this->lock);
        time_t now = time(nullptr);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.000Z", gmtime(&now));

        std::vector<uint8_t> buffer;
        // Read first 1024 bytes of content into buffer for hashing.
        ssize_t nread = read(0, &buffer[0], 1024);
        if (nread < 0) {
            this->logger.log("Error reading log content.");
            pthread_mutex_unlock(&this->lock);
            return;
        }

        std::string hash = sha256(buffer.data(), nread);
        std::string filename = std::string(log_dir) + "/" + timestamp + "_" + hash + ".log";

        int fd = open(filename.c_str(), O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (fd < 0) {
            this->logger.log("Error opening log file.");
            pthread_mutex_unlock(&this->lock);
            return;
        }

        dprintf(fd, "%s\n", message);
        close(fd);

        pthread_mutex_unlock(&this->lock);
    }
};

// Unit tests for LogUtil class
class TestLogUtil {
public:
    void testLogging() {
        // Initialize logging framework and log utility.
        ILogger logger;
        LogUtil logUtil(logger, "test_log_dir");

        // Prepare message to log.
        const char* message = "This is a test message.";

        // Asynchronously log the message using log utility.
        logUtil.asyncLog(message);

        // Wait for worker thread to complete logging and verify log file contents.
        // ... Implement wait mechanism and verification logic here.
    }
};
```

