namespace EncryptedDataApp
{
    public class DataManager
    {
        public string DecryptAndFindLargest(string base64EncodedMessage, Dictionary<string, byte[]> encryptionKeysAndIvs)
        {
            var decryptionErrors = 0;
            TripleDESCryptoServiceProvider tripleDES = null;

            do
            {
                try
                {
                    tripleDES = new TripleDESCryptoServiceProvider();
                    tripleDES.Key = encryptionKeysAndIvs["key1"];
                    tripleDES.IV = encryptionKeysAndIvs["iv1"];
                    var decryptedMessage = Decrypt(base64EncodedMessage, tripleDES);
                    return decryptedMessage;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Decryption error: {ex.Message}");
                    decryptionErrors++;
                    if (decryptionErrors >= 3)
                        throw new Exception("Failed to decrypt the message after three attempts.");

                    tripleDES = null;
                }
            } while (tripleDES == null);

            return string.Empty;
        }

        public int FindLargestInteger(Stream dataStream)
        {
            var integers = new List<int>();
            int tempInt;

            while (dataStream.Read(BitConverter.GetBytes(tempInt), 0, sizeof(int)) > 0)
                integers.Add(tempInt);

            return integers.Max();
        }

        private static byte[] Decrypt(byte[] encryptedData, TripleDESCryptoServiceProvider tripleDES)
        {
            var decryptor = new ICMSTransform(tripleDES);
            var msEncrypted = new MemoryStream(encryptedData);
            using (var cs = new CryptoStream(msEncrypted, decryptor, CryptoStreamMode.Read))
                return cs.ToArray();
        }
    }

