using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace AuthenticationService.Controllers
{
    public class AuthController : ControllerBase
    {
        private readonly ILogger<AuthController> _logger;
        private readonly DatabaseContext _context;
        private readonly AuthSettings _settings;
        private readonly ExternalAuthService _externalAuthService;

        public AuthController(ILogger<AuthController> logger, DatabaseContext context, IOptions<AuthSettings> settings, ExternalAuthService externalAuthService)
        {
            _logger = logger;
            _context = context;
            _settings = settings.Value;
            _externalAuthService = externalAuthService;
        }

        [HttpPost("login")]
        public async Task<IActionResult> Login([FromBody] LoginRequest model)
        {
            if (!ModelState.IsValid) return BadRequest(ModelState);

            var user = await _context.Users
                .Where(u => u.Username == model.Username)
                .FirstOrDefaultAsync();

            if (user == null) return NotFound("Invalid username or password.");

            // Generate MD5 hash for comparison with incoming hash from client
            var md5 = MD5.Create();
            var hashedPassword = md5.ComputeHash(Encoding.UTF8.GetBytes(model.Password));
            var hashedStoredPassword = new byte[hashedPassword.Length];
            Buffer.BlockCopy(hashedPassword, 0, hashedStoredPassword, 0, hashedPassword.Length);

            if (!user.HashedPassword.SequenceEqual(hashedStoredPassword))
                return Unauthorized("Invalid username or password.");

            // Simulate network latency and service outages from external auth service
            var response = await _externalAuthService.VerifyCredentialsAsync(user.Username, hashedPassword);

            if (!response.Success) return BadRequest(response.ErrorMessage);

            // Log authentication attempt for auditing and anomaly detection
            _logger.LogInformation("Authentication successful: {Username}", user.Username);

            return Ok(new AuthResponse { AccessToken = "Generated access token" });
        }
    }
}

// DatabaseContext, ExternalAuthService, LoginRequest, AuthResponse classes are omitted for brevity
