// 1. Data Loading and Deserialization
public class DataLoader
{
    private readonly ILogger<DataLoader> _logger;

    public async Task<JObject[]> LoadAndDeserializeAsync(string filePath)
    {
        var data = new JObject[];
        using (var stream = File.OpenRead(filePath))
        {
            var jsonSerializerOptions = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
            var deserializer = JsonDocument.CreateAsync(stream, jsonSerializerOptions);
            while (await deserializer.MoveNextAsync())
            {
                try
                {
                    data.Add(deserializer.RootElement.GetProperties().ToObject<JObject>());
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Failed to deserialize data: {FilePath}", filePath);
                }
            }
        }
        return data;
    }
}

