public class DisposableResourceScope : IDisposable
{
    private readonly ILogger<DisposableResourceScope> _logger;
    private bool _disposedValue;

    public DisposableResourceScope(ILogger<DisposableResourceScope> logger)
    {
        _logger = logger;
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!_disposedValue)
        {
            if (disposing)
            {
                // Dispose managed state (managed objects).
            }

            // Release unmanaged resources (unmanaged objects) and override finalizer below.
            _disposedValue = true;
        }
    }

    public void ReportError()
    {
        _logger.LogError("Resource contention or exhaustion");
    }

    public void Dispose()
    {
        // Do not change this code. Put cleanup code in Dispose(bool disposing) above.
        Dispose(disposing: true);
        GC.SuppressFinalize(this);
    }
}

