    int key;
    int value;
} Record;

void InitializeAndPersistRecords(size_t num_records, size_t range, unsigned long seed, const char* db_connection_str,
                                  size_t max_retries, unsigned timeout, pthread_rwlock_t *read_write_lock) {
    // Allocate memory for offsets, keys, and records arrays
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    Record* records = calloc(num_records, sizeof(Record));

    // Initialize offsets and keys with sequential values
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i;
        keys[i] = i;
    }

    // Randomly initialize each record's value
    srand(seed);
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < num_records; ++i) {
        Record* rec = &records[i];
        int val = rand() % range;
        pthread_mutex_lock(&mutex);
        rec->offset = offsets[i];
        rec->key = keys[i];
        rec->value = val;
        pthread_mutex_unlock(&mutex);
    }

    // Connect to the database and implement backoff strategy for retries and timeouts
    sqlite3* db = NULL;
    int rc;
    int retry_count = 0;
    while (true) {
        if ((rc = sqlite3_open(db_connection_str, &db)) == SQLITE_OK) break; // Open the database connection
        if (retry_count >= max_retries || ++retry_count > timeout) {
            fprintf(stderr, "Failed to connect to database: %s\n", sqlite3_errmsg(db));
            sqlite3_close(db);
            free(offsets); free(keys); free(records);
            return;
        }
        usleep(1000 * retry_count); // Backoff strategy
    }

    // Acquire write lock and atomically insert records into the database, adjusting batch sizes based on performance metrics and system load
    pthread_rwlock_wrlock(read_write_lock);
    int batchSize = 100; // Adjust this based on real-time load and system health
    for (size_t i = 0; i < num_records; ++i) {
        Record* rec = &records[i];
        // Persist the record to the database here
    }
    pthread_rwlock_unlock(read_write_lock);

    // Release resources and log completion
    sqlite3_close(db);
    free(offsets); free(keys); free(records);
}
```

