['```cpp
#include <memory>
#include <string>
#include <list>
#include <mutex>
#include <condition_variable>
#include <future>
#include <system_error>
#include <stdexcept>

class Node final {
public:
    std::shared_ptr<Node> next;
    std::shared_ptr<Node> prev;
    std::string value;

    Node(const std::string& value) : value(value), next(nullptr), prev(nullptr) {}
};

class DoublyLinkedList {
public:
    void insert(const std::string& target, const std::shared_ptr<Node> newNode);

private:
    std::list<std::shared_ptr<Node>> nodes;
    mutable std::mutex listMutex;
    std::condition_variable cv;
};

void DoublyLinkedList::insert(const std::string& target, const std::shared_ptr<Node> newNode) {
    std::unique_lock<std::mutex> lock(listMutex);
    auto it = nodes.begin();

    // Find the position where to insert the new node
    for (; it != nodes.end() && it->get()->value != target; ++it) {}

    if (it == nodes.end()) {
        // Append the new node if the target is not found
        nodes.push_back(newNode);
        newNode->next = nodes.empty() ? nullptr : nodes.back();
        newNode->prev = nodes.empty() ? nullptr : &*--nodes.end();
    } else {
        // Insert the new node after the target node
        newNode->value = target;
        newNode->next = it;
        newNode->prev = it->get()->prev;
        if (newNode->prev) {
            newNode->prev->get()->next = newNode.get();
        } else {
            nodes.erase(it);
        }
        it->get()->prev = newNode.get();
    }

    lock.unlock();
    cv.notify_one();
}

// Optional: Async logging with error handling and retries
struct LogEntry {
    std::string value;
};

class AsyncLogger {
public:
    // Constructor initializes a future object for the logged entry
    AsyncLogger(DoublyLinkedList& list) : list(list), logFuture(std::async(&AsyncLogger::log, this, list)) {}

    void log(const std::string& value);
    LogEntry getLoggedValue();

private:
    DoublyLinkedList& list;
    std::future<void> logFuture;
};

void AsyncLogger::log(DoublyLinkedList& list, const std::string& value) {
    // Implement asynchronous logging with retries and error handling here.
}

LogEntry AsyncLogger::getLoggedValue() {
    logFuture.wait();
    // Return the logged entry if available or throw an exception if not found.
}
```
