#include <boost/program_options.hpp>
#include <spdlog/spdlog.h>
#include <blueslip/blueslip.h>

namespace RandomEngine {
class MersenneTwister {
public:
    explicit MersenneTwister(unsigned long seed);
    ~MersenneTwister();
    MersenneTwister(const MersenneTwister&) = delete;
    MersenneTwister& operator=(const MersenneTwister&) = delete;

    double uniform();
    double normal();
    int uniformInt();
    int normalInt();
    static void seed_all_instances(unsigned long seed);

private:
    std::mt19937 engine{seed};
    mutable std::mutex mtx;
    bool initialized = false;
    unsigned long seed_;
};

MersenneTwister::MersenneTwister(unsigned long seed) : seed_(seed) {}

MersenneTwister::~MersenneTwister() {}

double MersenneTwister::uniform() {
    std::lock_guard<std::mutex> lck(mtx);
    if (!initialized) {
        initialized = true;
        engine.seed(seed_);
    }
    return engine();
}

double MersenneTwister::normal() {
    double u1 = uniform(), u2 = uniform();
    return sqrt(-2.0 * log(u1)) * cos(2 * M_PI * u2);
}

int MersenneTwister::uniformInt() {
    std::lock_guard<std::mutex> lck(mtx);
    if (!initialized) {
        initialized = true;
        engine.seed(seed_);
    }
    return static_cast<int>(engine() * std::numeric_limits<unsigned int>::max());
}

int MersenneTwister::normalInt() {
    int u1 = uniformInt(), u2 = uniformInt();
    auto norm = (static_cast<double>(u1) / static_cast<double>(std::numeric_limits<unsigned int>::max())) * 6;
    return static_cast<int>(norm + 3);
}

void MersenneTwister::seed_all_instances(unsigned long seed) {
    std::lock_guard<std::mutex> lck(mtx);
    engine.seed(seed);
}
} // namespace RandomEngine

