    public Response updateResource(@Valid UUID id, @NotNull byte[] payload, @NotNull String checksum) {
        Resource resource = resources.getUnchecked(id);
        if (!resource.validateChecksum(checksum)) {
            throw new IllegalArgumentException("Invalid checksum");
        }

        PutItemRequest putRequest = new PutItemRequest()
                .withItem(Map.of(
                        "id", AttributeValue.fromUuid(id),
                        "version", AttributeValue.fromN(resource.getVersion()),
                        "data", AttributeValue.fromBinary(payload)
                ))
                .withTableName("resources");

        PutItemResponse response = new RetryableAdapter<>(putRequest, getDynamoDbRetryPolicy())
                .execute(dynamoDbClient);

        // Logging, monitoring, and other post-processing tasks here

        return Response.success();
    }

    public Response deleteResource(@Valid UUID id) {
        Optional<Resource> optionalResource = resources.getIfPresent(id);
        if (!optionalResource.isPresent()) {
            return Response.notFound();
        }

        Resource resource = optionalResource.get();
        resource.markAsInactive();
        PutItemResponse putResponse = new RetryableAdapter<>(new PutItemRequest()
                .withItem(Map.of(
                        "id", AttributeValue.fromUuid(id),
                        "version", AttributeValue.fromN(resource.getVersion()),
                        "data", AttributeValue.fromBinary(resource.getData())
                ))
                .withTableName("resources"), getDynamoDbRetryPolicy()
        ).execute(dynamoDbClient);

        if (!putResponse.hasItems()) {
            return Response.error();
        }

        // Fallback default template handling, resource recovery and other tasks here

        return Response.success();
    }

    private DynamoDbRetryPolicy getDynamoDbRetryPolicy() {
        RetryPolicy retryPolicy = new RetryPolicy.Standard(MAX_RETRIES, RETRY_BACKOFF_FACTOR);
        retryPolicy = retryPolicy.withMaxErrorPercentage(50)
                .withWaitTimeStrategy(new ExponentialBackoffSpecificWaitTimeStrategy(RETRY_BACKOFF_FACTOR));
        return retryPolicy;
