typedef struct {
    char *name;
    size_t count;
} BookRef;

typedef struct {
    BookRef **books;
    size_t num_threads;
    size_t total_count;
} Bundle;

void *parse_bundle(void *arg) {
    Bundle *b = arg;
    char line[1024];
    while (fgets(line, sizeof(line), b->file)) {
        // Process the line and increment the appropriate book count
        // ... (Implement line processing here)
    }
    return NULL;
}

void init_bundle(Bundle *b, const char *path, const char **book_names, size_t num_books) {
    b->file = fopen(path, "r");
    if (!b->file) {
        fprintf(stderr, "Error: Failed to open file %s\n", path);
        exit(EXIT_FAILURE);
    }
    b->num_threads = numsystemprocessors();
    b->books = malloc(num_books * sizeof(BookRef*));

    for (size_t i = 0; i < num_books; ++i) {
        b->books[i] = calloc(1, sizeof(BookRef));
        b->books[i]->name = strdup(book_names[i]);
        b->books[i]->count = 0;
    }
}

void free_bundle(Bundle *b) {
    for (size_t i = 0; i < b->num_threads; ++i) {
        free(b->books[i]->name);
        free(b->books[i]);
    }
    free(b->books);
    fclose(b->file);
}

void log_error(const char *message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

void log_info(const char *message) {
    printf("[INFO] %s\n", message);
}

int main() {
    const char *book_names[] = {"Genesis", "Exodus", ... /* Add all Old Testament books here */ };
    size_t num_books = sizeof(book_names) / sizeof(char*);

    Bundle b;
    init_bundle(&b, "path/to/resource.txt", book_names, num_books);

    pthread_t threads[num_threads];
    for (size_t i = 0; i < b.num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, parse_bundle, &b)) {
            log_error("Failed to create thread");
            free_bundle(&b);
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < b.num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Book counts:\n");
    for (size_t i = 0; i < num_books; ++i) {
        printf("%s: %zu\n", b.books[i]->name, b.books[i]->count);
    }

    free_bundle(&b);
    return EXIT_SUCCESS;
}
```

This code assumes that the resource file follows a simple format with one book reference per line and no blank lines or comments. The function `parse_bundle()` should be updated to handle the actual parsing of each line, counting occurrences of valid book names, and ignoring punctuation and special characters. Also, don't forget to add support for all Old Testament books in the book_names array and optimize the code as required for your specific use case.']

[' Here's a JavaScript function that fulfills the requirements:

```javascript
class FooterLoader {
  constructor() {
    this.scripts = [];
    this.footerHtml = '<div id="footer"></div>';
    this.document = document;
  }

  addScript(src) {
    if (!src || !typeof src === 'string' || typeof src !== 'object' || !('type' in src) || !('src' in src)) {
      console.warn(`Invalid script object: ${JSON.stringify(src)}`);
      return;
    }

    const type = src.type.toLowerCase();
    const validTypes = ['text/javascript', 'application/javascript', 'text/css'];

    if (!validTypes.includes(type)) {
      console.warn(`Invalid MIME type for script: ${type}`);
      return;
    }

    const url = src.src;
    if (!isValidUrl(url)) {
      console.warn(`Invalid URL for script: ${url}`);
      return;
    }

    this.scripts.push({ ...src, isLoaded: false, error: null });
  }

  async load() {
    const promises = this.scripts.map(async (script) => {
      try {
        const scriptTag = document.createElement('script');
        scriptTag.src = script.src;
        scriptTag.type = script.type;
        await new Promise((resolve) => {
          scriptTag.onload = () => {
            script.isLoaded = true;
            resolve();
          };
        });
        document.querySelector('#footer').appendChild(scriptTag);
      } catch (error) {
        script.error = error;
        console.error(`Error loading script: ${JSON.stringify(script)}`, error);
      }
    });

    await Promise.all(promises);
  }

  getFooterHtml() {
    const loadedScripts = this.scripts.filter((script) => script.isLoaded).map((script) => `<script src="${script.src}" type="${script.type}"></script>`);
    return this.footerHtml + loadedScripts.join('\n');
  }
}

// Helper function to check if a URL is valid
function isValidUrl(url) {
  // Add your URL validation logic here, e.g., using a library like 'url-validator'
  const urlValidator = require('url-validator');
  return urlValidator.isHttpOrHttps(url);
}
```

This code uses a custom `FooterLoader` class to manage script insertion into the footer section of an HTML document. The `addScript()` method validates each script object and stores them in an array for later loading, while the `load()` method asynchronously loads all the scripts using Promises.

The `getFooterHtml()` method returns the HTML string containing only the successfully loaded scripts, and the footer itself remains intact even if some scripts fail to load due to proper error handling. Additionally, the code is modular, testable, and easy to extend by developers.']

