(function () {
    'use strict';

    angular
        .module('projectManagement')
        .service('dialogFieldService', DialogFieldService);

    function DialogFieldService($http, $q, localStorageService) {
        var service = this;

        // Fields cache
        var fieldsCache = {};
        var refreshTime = 60000; // Cache duration (ms)

        // Rate limit variables
        var requestCounter = 0;
        var maxRequests = 10;
        var delayIncreaseFactor = 2;

        // Set up the service methods
        service.refreshFields = refreshFields;
        service.getFieldByName = getFieldByName;
        service.setFieldByName = setFieldByName;

        function refreshFields(fieldNames) {
            var deferred = $q.defer();

            if (canRefresh()) {
                clearCache();
                requestCounter++;

                $http.get('api/dialog-fields')
                    .then(handleApiResponse)
                    .finally(function () {
                        deferred.resolve();
                    });
            } else {
                deferred.resolve();
            }

            return deferred.promise;
        }

        function handleApiResponse(response) {
            var fields = response.data;

            updateCache(fields);

            fieldNames.forEach(function (fieldName) {
                if (fields[fieldName]) {
                    postRefreshMessage(fieldName);
                }
            });
        }

        function getFieldByName(name) {
            return fieldsCache[name];
        }

        function setFieldByName(name, value) {
            if (fieldsCache[name]) {
                fieldsCache[name] = value;
                postRefreshMessage(name);
            }
        }

        // Helper functions

        function canRefresh() {
            var now = new Date().getTime();

            return (requestCounter < maxRequests) && (now - localStorageService.get('lastApiCall') > refreshTime);
        }

        function clearCache() {
            localStorageService.set('lastApiCall', new Date().getTime());
            fieldsCache = {};
        }

        function updateCache(fields) {
            fields.forEach(function (field) {
                fieldsCache[field.name] = field;
            });
        }

        function postRefreshMessage(fieldName) {
            // Post a message to the parent window here
        }
    }
})();
