// Function to create a promise-based wrapper around asynchronous functions, ensuring proper error propagation
function asyncWrapper(fn) {
  return (...args) => q.Promise((resolve, reject) => {
    fn(...args, (err, result) => (err ? reject(err) : resolve(result)));
  });
}

// Async function to download and process a resource bundle
async function processResourceBundle({ id, priority }) {
  // Check if the bundle has already been processed recently, returning the cached result
  const cachedResult = await redisClient.get(`processed_bundle_${id}`);
  if (cachedResult) return JSON.parse(cachedResult);

  // Download the resource bundle from S3 and authenticate using OAuth2 tokens
  const bundleUrl = `https://s3.amazonaws.com/${process.env.S3_BUCKET}/${id}.gz`;
  const response = await axios({ url: bundleUrl, method: 'GET', responseType: 'arraybuffer' });

  // Extract the gzipped JSON from the downloaded file and parse it
  const buffer = zlib.gunzipSync(response.data);
  const jsonBundle = JSON.parse(buffer.toString());

  try {
    // Process the bundle and update the Redis cache with the result, or in case of an error, store the error details
    const processedResult = await asyncWrapper(processBundle)(jsonBundle);
    redisClient.set(`processed_bundle_${id}`, JSON.stringify(processedResult), 'EX', 60 * 60); // Cache result for 1 hour
    return processedResult;
  } catch (error) {
    console.error(`Error processing bundle ${id}: ${JSON.stringify(error)}`);
    redisClient.set(`failed_bundle_${id}`, JSON.stringify(error), 'EX', 60 * 60); // Cache error details for 1 hour
    throw new ProcessingError(error);
  }
}

