```java
class FileManager {
    private AtomicBoolean isDeleting = new AtomicBoolean(false);
    private ReentrantLock lock = new ReentrantLock();

    public void deleteFileIfNotExist(String filePath) {
        if (lock.tryLock()) {
            try {
                if (!isDeleting.get() && !Files.exists(Paths.get(filePath))) {
                    Files.deleteIfExists(Paths.get(filePath));
                }
            } finally {
                lock.unlock();
            }
        }
    }
}
