```csharp
using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

public class RequestManager {
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(5); // Adjust the concurrency limit as needed.
    private readonly ConcurrentQueue<Task> _queue = new ConcurrentQueue<Task>();

    public async Task ExecuteAsync(Task task) {
        await _semaphore.WaitAsync();
        try {
            _queue.Enqueue(task);
            if (_queue.Count == 1) await task; // Execute the first task in the queue immediately.
        } finally {
            _semaphore.Release();
        }
    }
}
```

