```java
import java.io.*;
import java.util.concurrent.Callable;

public class ExternalCommandExecutorImpl implements ExternalCommandExecutor {
    private final ProcessBuilder _processBuilder;

    public ExternalCommandExecutorImpl(String... commandArgs) {
        _processBuilder = new ProcessBuilder(commandArgs);
    }

    @Override
    public void execute(String command) {
        try {
            _processBuilder.command(new String[]{"bash", "-c", command});
            start();
            waitForExit();
        } catch (IOException | InterruptedException e) {
            // Handle exceptions gracefully.
        }
    }

    private Process start() throws IOException, InterruptedException {
        return _processBuilder.start();
    }

    private void waitForExit() throws InterruptedException {
        _processBuilder.redirectErrorStream(ProcessBuilder.Redirect.APPEND_OUTPUT);
        _processBuilder.redirectOutput(ProcessBuilder.Redirect.toInputStream());
        Process process = start();
        process.waitFor();
    }

    @Override
    public String getOutput() {
        // Return the captured output stream as a string.
    }

    @Override
    public String getError() {
        // Return the captured error stream as a string.
    }
}
