    private bool IsTokenExpired(byte[] encryptedToken) => DateTime.UtcNow > GetTokenExpirationTime(encryptedToken);

    private DateTime GetTokenExpirationTime(byte[] encryptedToken) => Encoding.UTF8.GetString(EncryptToken(DateTime.UtcNow.AddHours(1).ToString())) <= DateTime.UtcNow;

