**UserProfileService.java**
```java
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import reactor.core.publisher.Mono;
import software.example.api.UserProfileApi;
import software.example.model.UserProfile;
import software.sabal.ehcache.EhCacheManager;

@Service
public class UserProfileService {
    @Autowired
    private UserProfileApi userProfileApi;

    @Autowired
    private EhCacheManager ehCacheManager;

    public Mono<UserProfile> getOrFetchUserProfile(String id) {
        return this.ehCacheManager.get(id, UserProfile.class)
            .switchIfEmpty(this.userProfileApi.getUserProfile(id)
                .onErrorResume(t -> this.retryPolicy(Mono.just(null)))
                .doOnSuccess(up -> ehCacheManager.put(id, up))
                .cache());
    }

    private Mono<Void> retryPolicy(Mono<UserProfile> mono) {
        return mono.delayElements(Duration.ofSeconds(5)).retryWhen(retries -> retries.flatMap(e -> {
            if (e instanceof RetryableException) {
                return Mono.just(1);
            } else {
                return Mono.error(e);
            }
        }));
    }
}
```

**UserProfileApi.java**
```java
import org.springframework.http.MediaType;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Mono;
import software.example.model.UserProfile;

public class UserProfileApi {
    private final WebClient client;

    public UserProfileApi(WebClient.Builder builder) {
        this.client = builder.baseUrl("https://external-api.com")
            .defaultHeader("Authorization", "Bearer TOKEN")
            .build();
    }

    public Mono<UserProfile> getUserProfile(String id) {
        return this.client.get()
            .uri("/user/{id}", id)
            .retrieve()
            .bodyToMono(UserProfile.class);
    }
}
