namespace RandomEngine {
    class MersenneTwister {
        std::mt19937 engine;
        std::mutex mtx;

    public:
        MersenneTwister() : engine(std::rand()) {}
        MersenneTwister(uint32_t seed) : engine(seed) {}
        ~MersenneTwister() = default;

        MersenneTwister(const MersenneTwister& other) {
            std::unique_lock<std::mutex> lock(other.mtx);
            engine.seed(other.engine.now());
        }

        MersenneTwister& operator=(const MersenneTwister& other) {
            std::unique_lock<std::mutex> lock(other.mtx);
            engine.seed(other.engine.now());
            return *this;
        }

        void seed_all_instances() {
