public class ProcessResourceBundle {
    private readonly IMetadataService _metadataService;
    private readonly string _connectionString;
    private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 10); // Concurrency limit

    public ProcessResourceBundle(IMetadataService metadataService, string connectionString) {
        _metadataService = metadataService;
        _connectionString = connectionString;
    }

    public async Task<(IDataReader Result, int Count)> ProcessResourceBundleAsync(string filePath) {
        try {
            using var stream = File.OpenRead(filePath); // Load the resource bundle into memory
            if (stream.Length <= 0) throw new Exception("Invalid resource bundle.");

            var metadataIdentifiers = await _metadataService.LookupMetadataAsync(GetMetadataIdentifiers());
            var sqlParameters = BuildSqlParameters(metadataIdentifiers);

            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            using var command = new SqlCommand("SELECT * FROM ResourceData WHERE Id IN @Ids", connection) {
                CommandType = CommandType.Text
            };
            command.Parameters.AddRange(sqlParameters.Values);

            using var reader = await command.ExecuteReaderAsync();
            return (reader, sqlParameters.Keys.Count);
        } catch (Exception ex) {
            Console.WriteLine($"Error processing resource bundle: {ex.Message}");
            throw;
        }
    }

    private IEnumerable<string> GetMetadataIdentifiers() {
        // Implement your logic to extract the metadata identifiers from the resource bundle here.
    }

    private Dictionary<string, SqlParameter> BuildSqlParameters(Dictionary<string, string> metadata) {
        return metadata.ToDictionary(k => k.Key, v => new SqlParameter(@$"@Id{v.Key}", v.Value));
    }
}
