Here's a simplified version of the `processTransactionStream` function:

```java
@Service
public class TransactionController {
    private final TransactionService transactionService;
    private final MetricsService metricsService;
    private final TracingService tracingService;

    // Constructor and @Autowired annotations omitted for brevity.

    public void processTransactionStream(InputStream inputStream) throws IOException, InterruptedException {
        DeserializationConfig deserializerConfig = configService.getDeserializationConfig();

        ObjectMapper objectMapper;
        if (deserializerConfig.isJson()) {
            objectMapper = new JsonFactory().createObjectMapper();
        } else if (deserializerConfig.isXml()) {
            objectMapper = new XmlMapper();
        } else if (deserializerConfig.isBinary()) {
            // Handle binary deserialization here
        }

        JsonNode node;
        Object obj;
        Transaction transaction;
        while ((node = objectMapper.readValue(inputStream, JsonNode.class)) != null) {
            try {
                obj = objectMapper.treeToVal(node);
                transaction = mapper.mapValues(obj, Transaction.class);

                if (shouldFilterTransaction(transaction)) {
                    transactionService.processTransaction(transaction);
                }

                metricsService.trackMetric(MetricsService.metricFor(transaction));
                tracingService.traceTransaction(TraceData.forTransaction(transaction));
