["```cpp
#include <list>
#include <memory>
#include <mutex>
#include <string>
#include <atomic>
#include <future>
#include <system_error>

struct Node {
    std::string value;
    std::shared_ptr<Node> prev, next;
};

class DoublyLinkedList {
public:
    void insert(const std::string& target, const std::shared_ptr<Node>& newNode) {
        std::unique_lock<std::mutex> lock(_listMutex);

        auto curr = _head.load();
        while (curr && curr->value != target) {
            curr = curr->next.load();
        }

        if (!curr) {
            _back.store(newNode, std::memory_order_release);
            return;
        }

        newNode->prev.store(curr, std::memory_order_release);
        newNode->next.store(curr->next.load(), std::memory_order_relaxed);
        if (curr->next) {
            curr->next->prev.store(newNode, std::memory_order_release);
        } else {
            _tail.store(newNode, std::memory_order_release);
        }
        curr->next.compare_exchange_strong(newNode, newNode, std::memory_order_relaxed);
    }

    // Asynchronous logging function with backpressure and retry logic
    void logEntryAsync(const std::shared_ptr<Node>& node) {
        auto task = [node]() {
            // Implement logging system here
            // Handle network failures, idempotency, and eventual consistency
        };

        _logTasks.emplace_back(task);

        // Backpressure mechanism (Adjust this based on resource availability)
        if (_logTasks.size() > _maxConcurrentLoggingTasks) {
            std::unique_lock<std::mutex> lock(_logTasksMutex);
            _logTasksCondVar.wait(lock, [this]() { return _logTasks.size() < _maxConcurrentLoggingTasks; });
        }
    }

private:
    std::list<std::shared_ptr<Node>> _nodes;
    std::atomic<std::shared_ptr<Node>> _head{nullptr}, _tail{nullptr};
    std::mutex _listMutex;
    std::condition_variable _logTasksCondVar;
    std::mutex _logTasksMutex;
    std::list<std::function<void()>> _logTasks;
    size_t _maxConcurrentLoggingTasks = 10; // Adjust based on resource availability and desired concurrency level
};
```

