                // Implement bulk insertion and batch processing to persist records asynchronously.

                await transaction.CommitAsync();
            }
            catch (DbException ex) when (_maxRetryAttempts > 0 && ex.GetBaseException().Message.Contains("Timeout expired"))
            {
                // Retry database operations with a backoff strategy if timeouts occur.
            }
            catch (Exception ex)
            {
