C Function:

```c
char* append_slash_if_needed(const char* str, size_t limit) {
    if (str == NULL || strlen(str) > limit) {
        return NULL;
    }
    char *result = malloc(strlen(str) + 1);
    strcpy(result, str);
    result[strlen(str)] = '/';
    result[strlen(str)+1] = '\0';
    return result;
}
