```java
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.reactive.EnableWebFluxSecurity;
import org.springframework.security.config.web.server.ServerHttpSecurity;
import org.springframework.security.oauth2.client.registration.ClientRegistrationRepository;
import org.springframework.security.oauth2.client.registration.InMemoryClientRegistry;
import org.springframework.security.oauth2.client.web.reactive.function.client.ServletOAuth2AuthorizedClientExchangeFilterFunction;
import org.springframework.security.web.server.SecurityWebFilterChain;

@Configuration
@EnableWebFluxSecurity
public class SecurityConfig {
    @Bean
    public InMemoryClientRegistry clientRegistry() {
        return new InMemoryClientRegistry();
    }

    @Bean
    public ServletOAuth2AuthorizedClientExchangeFilterFunction oauth2Login(ClientRegistrationRepository clientRegistrationRepository) {
        return new ServletOAuth2AuthorizedClientExchangeFilterFunction(clientRegistrationRepository);
    }

    @Bean
    public SecurityWebFilterChain securityWebFilterChain(ServerHttpSecurity http) throws Exception {
        http.csrf().disable()
                .authorizeExchange()
                    .pathMatchers("/api/**").hasAuthority("API_ACCESS")
                    .anyExchange().authenticated()
                .and().oauth2Login(oauth2Login())
                .and().build();
        return http.build();
    }
}
