```cpp
bool validateOAuthToken(const std::string& tokenResponse) {
    bool success = false;
    try {
        json j = json::parse(tokenResponse);
        if (!j.contains("access_token") || !j["access_token"].is_string() ||
            !j.contains("expires_in") || !j["expires_in"].is_number_unsigned() ||
            !j.contains("token_type") || j["token_type"] != "Bearer" ||
            j.find("refresh_token") == j.end()) {
            // Invalid token format, log the details and return false
            std::cout << "Invalid token format: " << tokenResponse << std::endl;
            return success;
        }

        auto expiresIn = j["expires_in"].get<unsigned int>();
        if (expiresIn <= 0) {
            // Token has expired, log the details and return false
            std::cout << "Token has expired: " << tokenResponse << std::endl;
            return success;
        }

        success = true;
    } catch (const std::exception& e) {
        // Handle JSON parsing errors or any other exceptions, log the details and return false
        std::cout << "Error parsing token response: " << e.what() << std::endl;
        return success;
    }

    // Token verification was successful, continue with additional steps (e.g., sending the token to the external service)
    // ...

    return success;
}
