    const retries = 3;
    let currentRetry = 0;

    const loadModule = () => {
      if (currentRetry >= retries) return reject(new Error(`Failed to load ${moduleName}`));

      loader[moduleName](dependencies, (err, mod) => {
        if (err) {
          currentRetry++;
