     while (idMap[id] !== current) {
       const temp = idMap[id];
       idMap[id] = current;
       id = temp;
     }

     return current;
   };

   const union = (id1, id2) => {
     let root1 = find(id1);
     let root2 = find(id2);

     if (root1 === root2) return;

     idMap[root2] = root1;
     rootIds.splice(rootIds.indexOf(root2), 1);
     rootIds.push(root1);
   };

   const connectedComponentsCount = () => rootIds.length;

   return { find, union, connectedComponentsCount };
}

async function traverseAndFilter(rootNode, filter) {
  // Offload heavy processing tasks to a background worker thread
  const cacheKey = `${rootNode.nodeType}${rootNode.id || rootNode.className}`;
  if (!caches.has(cacheKey)) {
    await new Promise((resolve) => worker.postMessage({ type: 'process', node: rootNode, filter }));
    await worker.onmessage.then((msg) => resolve(msg.data));
  }

  let results = [];
  for (const node of Array.from(rootNode.childNodes)) {
    const childResults = await traverseAndFilter(node, filter);
    results = results.concat(childResults);
  }

  const filteredResults = await filter.execute(rootNode, cacheKey);
  results = results.filter((result) => filteredResults.includes(result));

  // Perform disjointness checks and performance tracking using Union-Find data structure
  const pairs = [];
  for (const result of results) {
    const [id1, id2] = [result.id || result.className, result.id || result.className];
    const { find } = unionFind([id1, id2]);
    if (find(id1) !== find(id2)) {
      pairs.push([id1, id2]);
    }
  }

  analytics.logEvent('traverseAndFilter', { pairsCount: pairs.length });
  console.time(`Pair check for ${pairs.length} pairs`);
  const disjointPairs = pairs.map((pair) => unionFind([pair[0], pair[1]]).connectedComponentsCount() === 2 ? pair : null).filter(Boolean);
  console.timeEnd(`Pair check for ${pairs.length} pairs`);

  return disjointPairs;
}
```

  2. Here's a Java function using the Union-Find data structure:

```java
import java.util.*;

public class UnionFind {
    private int[] id;
    private int count;

    public UnionFind(int capacity) {
        this.count = capacity;
        this.id = new int[capacity];
        for (int i = 0; i < capacity; ++i) {
            id[i] = i;
        }
    }

    public void union(int p, int q) {
        int rootP = find(p);
        int rootQ = find(q);
        if (rootP != rootQ) {
            id[rootQ] = rootP;
            --count;
        }
    }

    public int find(int x) {
        while (x != id[x]) {
            x = id[x];
        }
        return x;
    }

    public int connectedComponentsCount() {
        return count;
    }
}

public class PairChecker {
    public static void main(String[] args) throws Exception {
        if (args.length != 1) {
            throw new IllegalArgumentException("Expected an integer array as input.");
        }

        int[] arr = Arrays.stream(args[0].split("\\s+")).mapToInt(Integer::parseInt).toArray();

        UnionFind uf = new UnionFind(arr.length);
        long startTime = System.currentTimeMillis();
        for (int i = 0; i < arr.length; ++i) {
            int root = uf.find(i);
            for (int j = i + 1; j < arr.length; ++j) {
                if (uf.connectedComponentsCount() > 1) {
                    long elapsedTime = System.currentTimeMillis() - startTime;
                    System.out.printf("Pair [%d, %d] connected: %.3f ms\n", i, j, elapsedTime);
                }
                uf.union(i, j);
            }
        }
        System.out.println("Disjoint pairs count: " + uf.connectedComponentsCount());
    }
}
```']

