fn create_and_set_directory(path: &str) {
    if !std::path::Path::new(&path).exists() {
        create_dir_all(path).expect("Failed to create directory.");
    }
    let mut paths = env::vars_os().filter(|v| v.eq("PATH")).collect::<Vec<_>>();
    if paths.is_empty() {
        eprintln!("Environment variable PATH not set.");
        return;
    }
    let mut path_vec: Vec<&str> = paths[0].to_str().unwrap().split(':').collect();
    let mut found = false;
    for dir in &path_vec {
        if dir.eq(path) {
            found = true;
            break;
        }
    }
    if !found {
        path_vec.push(path);
        env::set_var("PATH", path_vec.iter().collect::<String>());
    }
}
