public class PokemonWeaknessService {
    private static final Logger LOGGER = LoggerFactory.getLogger(PokemonWeaknessService.class);
    private static final ConcurrentLinkedQueue<Request> requestsQueue = new ConcurrentLinkedQueue<>();
    private static final AtomicBoolean circuitBreakerOpened = new AtomicBoolean(false);
    private Properties properties;
    private OkHttpClient okHttpClient;
    private StatefulRedisConnection<String, String> redisConnection;
    private int maxCacheSize;
    private Duration timeToLive;

    @Inject
    public PokemonWeaknessService(Properties properties) {
        this.properties = properties;
        configureOkHttpClient();
        configureRedisConnection();
        maxCacheSize = Integer.parseInt(properties.getProperty("max_cache_size"));
        timeToLive = Duration.ofMillis(Long.parseLong(properties.getProperty("time_to_live")));
    }

    private void configureOkHttpClient() {
        okHttpClient = new OkHttpClient().newBuilder()
                .connectTimeout(Duration.ofMinutes(5))
                .readTimeout(Duration.ofMillis(1000))
                .build();
    }

    private void configureRedisConnection() {
        RedisClient redisClient = RedisClient.create("redis://localhost");
        redisConnection = redisClient.connect().block();
    }

    public Mono<Map<String, String>> getWeaknesses(String pokemonId) {
        Map<String, String> weaknessCache = loadFromCache(pokemonId);

        if (!weaknessCache.isEmpty()) {
            return Mono.just(weaknessCache);
        }

        return Mono.defer(() -> {
            Request request = buildRequest(pokemonId);
            requestsQueue.add(request);

            return Retry.backoff(configuredRetryAttempts(), configuredBackoff())
                    .onRetryExceededThrow((ex, retrySignal) -> {
                        circuitBreakerOpened.set(true);
                        return Mono.error(new RuntimeException("Circuit breaker opened due to exceeded retry attempts"));
                    })
                    .flatMap(__ -> Mono.fromCallable(() -> executeRequestAndProcessResponse(request)))
                    .doFinally(__ -> handleQueue())
                    .doOnError(ex -> logError(ex))
                    .onErrorResume((ex) -> {
                        if (ex instanceof ReadTimeoutException && circuitBreakerOpened.get()) {
                            return Mono.error(new RuntimeException("Circuit breaker opened due to network timeout"));
                        } else {
                            return Mono.defer(() -> getWeaknesses(pokemonId));
                        }
                    });
        })
    }

    // Implement the remaining methods for cache management, error handling, logging, configuration and testing

    private int configuredRetryAttempts() {
        String retryCount = properties.getProperty("retry_attempts");
        return Integer.parseInt(retryCount);
    }

    private Duration configuredBackoff() {
        String backoffTime = properties.getProperty("backoff_time");
        return Duration.ofMillis(Long.parseLong(backoffTime));
    }

    private Request buildRequest(String pokemonId) {
