2. **Java Function (DisjointPairCount)**

```java
import java.util.*;

public class DisjointPairCount {
    private static int[] idArray;
    private static int[] size;

    public static long countDisjointPairs(int[] arr) {
        idArray = new int[arr.length];
        size = new int[arr.length];
        Arrays.fill(idArray, -1);
        Arrays.fill(size, 1);

        UnionFind uf = new UnionFind(arr.length);
        long count = 0;

        for (int i = 0; i < arr.length; ++i) {
            int root = uf.find(i);
            idArray[root] = arr[i];
            count += size[root] * (size[root] - 1) / 2;
        }

        for (int i = 0; i < arr.length; ++i) {
            int root = uf.find(i);
            long time = System.nanoTime();
            if (idArray[root] > 0) continue; // Element is already processed
            for (int j = i + 1; j < arr.length; ++j) {
                int otherRoot = uf.find(j);
                long time2 = System.nanoTime();
                if (idArray[otherRoot] > 0 && uf.connected(root, otherRoot)) continue; // Element or its neighbor is already processed
                System.out.printf("Pair (%d, %d) took %.6f ms\n", i, j, (time2 - time) / 1_000_000);
            }
        }

        return count;
    }

    static class UnionFind {
        private int[] id;
        private int[] rank;

        UnionFind(int n) {
            id = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; ++i) {
                id[i] = i;
                rank[i] = 1;
            }
        }

        int find(int x) {
            return id[x] == x ? x : id[x] = find(id[x]);
        }

        boolean connected(int x, int y) {
            return find(x) == find(y);
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) return;

            if (rank[rootX] > rank[rootY]) id[rootY] = rootX;
            else id[rootX] = rootY;

            if (rank[rootX] == rank[rootY]) ++rank[rootY];
        }
    }
}
```']

