```php
function updateClinicStatus($clinicId, $status) {
    const MAX_RETRIES = 10;
    const BACKOFF_FACTOR = 2;
    $retryCount = 0;

    do {
        try {
            // Attempt the update and catch any errors
            updateClinicStatusTransactionally($clinicId, $status);
            break;
        } catch (\Exception $e) {
            if ($retryCount < MAX_RETRIES) {
                usleep(pow(2, $retryCount + 1) * 1000000); // Exponential backoff in microseconds
                ++$retryCount;
            } else {
                throw new Exception("Update failed after max retries.");
            }
        }
    } while (true);
}
