};

// Constructor for Logger class
Logger::Logger(const std::shared_ptr<boost::asio::ip::tcp::socket>& socket)
    : socket_(socket), threshold_(1.0) {}

// Implementation of the other Logger functions, along with additional helper functions
void Logger::start() {
    // Start monitoring and asynchronous flushing threads
    std::thread(std::bind(&Logger::monitor, this)).detach();
    thread_ = std::thread(&Logger::flush, this);
}

void Logger::stop() {
    running_ = false;
    cv_.notify_all();
    if (thread_.joinable()) {
        thread_.join();
    }
}

void Logger::log(const std::string& level, const std::string& msg) {
    // Append log message to the buffer and notify flushing thread
    std::unique_lock<std::mutex> lock(mtx_);
    auto now = std::chrono::system_clock::now().time_since_epoch().count();
    LogMessage logMsg{ std::to_string(now), level, msg };
    buffer_.push(logMsg);
    cv_.notify_one();
}

void Logger::flush() {
    // Implement asynchronous background flushing logic here
}

