['1. Decryption Module:

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDESDecrypter
{
    private readonly TripleDESCryptoServiceProvider _crypto;

    public TripleDESDecrypter(byte[] key, byte[] iv)
    {
        _crypto = new TripleDESCryptoServiceProvider();
        _crypto.Key = key;
        _crypto.IV = iv;
    }

    public string DecryptBase64(string encryptedData)
    {
        try
        {
            var decodedBytes = Convert.FromBase64String(encryptedData);
            var decryptedBytes = Decrypt(decodedBytes);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error during decryption: {ex}");
            throw;
        }
    }

    private byte[] Decrypt(byte[] encryptedData)
    {
        var transform = _crypto.CreateDecryptor();
        using (MemoryStream memoryStream = new MemoryStream(encryptedData))
        using (CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Read))
        using (MemoryStream outputStream = new MemoryStream())
        {
            cryptoStream.CopyTo(outputStream);
            return outputStream.ToArray();
        }
    }
}
```

