        public EncryptedMessageProcessor(ILogger<EncryptedMessageProcessor> logger, IOptions<QueueSettings> queueOptions, IOptions<CryptoSettings> cryptoOptions)
        {
            _logger = logger;
            _queueClient = new MessageQueueClient(queueOptions.Value);
            _cryptoProvider = CreateTripleDESCryptoProvider(cryptoOptions.Value.Key, cryptoOptions.Value.Iv);
            _keyManager = new RotatingKeyManager(_cryptoProvider);
            _maxDegreeOfParallelism = queueOptions.Value.MaxConcurrentProcessors;
            _semaphore = new SemaphoreSlim(_maxDegreeOfParallelism);
        }

        public void ProcessMessages()
        {
            var workerTasks = Enumerable.Range(0, _maxDegreeOfParallelism)
                .Select(i => Task.Factory.StartNew(() => Worker()));

            Task.WhenAll(workerTasks);
        }

        private async void Worker()
        {
            while (true)
            {
                await _semaphore.WaitAsync();
                try
                {
                    var message = await _queueClient.GetNextMessageAsync();
                    DecryptAndProcess(message);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing message");
                }
                finally
                {
                    _semaphore.Release();
                }
            }
        }

        private void DecryptAndProcess(string encryptedMessage)
        {
            try
            {
                var decrypted = DecryptBase64(encryptedMessage);
                ProcessDecryptedMessage(decrypted);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process message");
            }
        }

        private byte[] DecryptBase64(string base64EncodedData)
        {
            var decryptedBytes = Convert.FromBase64String(base64EncodedData);
            using (var cryptoProvider = _cryptoProvider.CreateDerivedKeys())
            {
                return TripleDES.Create().Decrypt(decryptedBytes, cryptoProvider.CreateEncryptor());
            }
        }

        private void ProcessDecryptedMessage(byte[] message)
        {
            // Implement message processing logic here
        }

        private static TripleDESCryptoServiceProvider CreateTripleDESCryptoProvider(string key, byte[] iv)
        {
            var cryptoProvider = new TripleDESCryptoServiceProvider();
            cryptoProvider.Key = Encoding.UTF8.GetBytes(key);
            cryptoProvider.IV = iv;
            return cryptoProvider;
        }

        public void Dispose()
        {
            _queueClient?.Dispose();
        }
    }
}
```

