public class EncryptedDataStream
{
    private readonly string _url;
    private readonly TripleDES _tripleDes;
    private readonly IQueue _queue;
    private readonly int _maxRetries;
    private int _retryCount;

    public EncryptedDataStream(string url, (byte[] key, byte[] iv) encryptionKeys)
    {
        _url = url;
        _tripleDes = new TripleDES(encryptionKeys.key, encryptionKeys.iv);
        _queue = new ConcurrentQueue<Base64EncodedMessage>();
        _maxRetries = 5;
    }

    public async Task ProcessAsync()
    {
        while (true)
        {
            try
            {
                // Retrieve Base64-encoded message from data source and decrypt it
                var base64Message = await _httpClient.GetStringAsync(_url);
                var decryptedMessage = Decrypt(base64Message);

                // Process the message and enqueue for further processing if necessary
                // ...

                _queue.Enqueue(decryptedMessage);
            }
            catch (Exception ex)
            {
                if (_retryCount < _maxRetries)
                {
                    _monitoringService.LogError(ex);
                    _retryCount++;
                    await Task.Delay(GetExponentialBackoff());
                }
            }
        }
    }
}

