void insertAfterInForwardList(std::forward_list<std::string>& list, const std::string& search, const std::string& insert) {
    auto it = list.begin();
    if (it == list.end() || *it != search) return; // Not found, do nothing

    auto next = std::next(it);
    list.insert_after(it, insert);
}
```"]

