from datetime import datetime, timedelta

app = FastAPI()
client = WebApplicationClient(redirect_uris="http://localhost:8000/callback", client_id="your_client_id")

def create_access_token(data: dict, expires_minutes=30):
    to_encode = data.copy()
    expire = datetime.utcnow() + timedelta(minutes=expires_minutes)
    to_encode.update({"exp": expire})
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm="HS256")
    return encoded_jwt

@app.get("/login/{provider}")
async def login(provider: str):
    # Redirect to external identity provider for authentication and authorization
    authorization_url, state = client.prepare_request_uri(
        "authorize",
        scope=["openid", "email", "profile"],
        redirect_uri="http://localhost:8000/callback"
    )
    return {"Authorization URL": authorization_url}

@app.get("/callback")
async def callback():
    # Handle the incoming request and retrieve the token from the state parameter
    code = request.query_params["code"]
    tokens = client.fetch_token(code=code, state=request.state)
    userinfo = tokens["id_token"].claims

    # Check if the user is already registered or create a new account
    user = get_user(db, userinfo["sub"])
    if not user:
        user = User(username=userinfo["email"], **userinfo)
        db.add(user)
        db.commit()
        db.refresh(user)

    # Verify the password and apply MFA if required
    if not check_password(user.password, hashed_password):
        raise HTTPException(status_code=401, detail="Invalid password")

    # Generate a JWT access token and return it
    access_token = create_access_token({"sub": user.username})
    return {"access_token": access_token}
```

