        $this->redis = $redis;
        $this->httpClient = $httpClient;
        $this->rateLimiter = $rateLimiter;
        $this->storageServiceUrl = $storageServiceUrl;
        $this->logger = $logger;
    }

    public function processRequest(array $requestData): Promise {
        // Validate request

        // Rate limit check
        $this->rateLimiter->check($requestData['client_id']);

        // Retrieve necessary data from in-memory cache or external storage service
        $key = "oauth:{$requestData['request_id']}";

        if ($this->redis->exists($key)) {
            return Promise::resolve($this->redis->get($key));
        }

        // Asynchronously fetch data from external storage service and store the results in cache
        $fetchPromise = call(function() use ($requestData, $storageServiceUrl) {
            try {
                $response = $this->httpClient->get("{$storageServiceUrl}/api/key", [
                    'query' => $requestData
                ]);

                if ($response->getStatusCode() !== 200) {
                    throw new Exception("Error fetching key data");
                }

                return $response->getBody();
