```csharp
using System;
using System.IO;
using System.Security.Cryptography;
// ...
public class MessageDecrypter
{
    private readonly TripleDESCryptoServiceProvider _cryptoServiceProvider;

    public MessageDecrypter(string key, string iv)
    {
        _cryptoServiceProvider = new TripleDESCryptoServiceProvider();
        _cryptoServiceProvider.Key = Encoding.ASCII.GetBytes(key);
        _cryptoServiceProvider.IV = Encoding.ASCII.GetBytes(iv);
    }

    public string Decrypt(string base64EncodedMessage)
    {
        var message = Convert.FromBase64String(base64EncodedMessage);
        using (var memoryStream = new MemoryStream(message))
        {
            using (var cryptoStream = new CryptoStream(memoryStream, _cryptoServiceProvider.CreateDecryptor(), CryptoStreamMode.Read))
            {
                var decryptedData = new byte[cryptoStream.ReadByte()];
                using (var memoryStream2 = new MemoryStream(decryptedData))
                {
                    cryptoStream.CopyTo(memoryStream2);
                }
                return Encoding.ASCII.GetString(decryptedData);
            }
        }
    }
}
```

