4. Bloom filter for duplicate detection (BloomFilter)
   - Efficiently identifies duplicates within log entries while meeting specified thresholds on false positive rates and memory usage.

```cpp
#include <unordered_bitset>

class BloomFilter {
public:
    explicit BloomFilter(size_t k, float p) : _k(k), _p(p), _filter(_k * 8) {}

    void add(const std::string& key) {
        boost::hash<std::string> hashFunc;
        for (int i = 0; i < _k; ++i) {
            auto idx = hashFunc(key) % _filter.size();
            _filter[idx] |= 1 << (idx % 64);
        }
    }

    bool contains(const std::string& key) const {
        boost::hash<std::string> hashFunc;
        for (int i = 0; i < _k; ++i) {
            auto idx = hashFunc(key) % _filter.size();
            if (!( _filter[idx] & (1 << (idx % 64)) ))
                return false;
        }
        return true;
    }

private:
    const int _k;
    const float _p;
    std::unordered_bitset<64> _filter;
};
```

