1. Initialize Bloom Filter:

```cpp
#include <bitset>

class BloomFilter {
public:
    BloomFilter(size_t size, float falsePositiveProbability)
        : data_(size, true), k_(mersengerFunctionCount(falsePositiveProbability)), n_(0) {}

    void add(const std::string& key) {
        for (int i = hash(key, 0); i < data_.size(); i = (i + k_) % data_.size()) {
            data_[i] = false;
        }
        n_++;
    }

    bool contains(const std::string& key) const {
        for (int i = hash(key, 0); i < data_.size(); i = (i + k_) % data_.size()) {
            if (data_[i]) return false;
        }
        return true;
    }

private:
    std::bitset data_;
    int k_, n_;

    int hash(const std::string& key, int i) const {
        uint32_t hash = 1;
        for (char c : key) {
            hash = (hash << 5) + hash + c;
            hash &= ((uint64_t)1 << 32) - 1;
            hash += i;
        }
        return hash % data_.size();
    }

    static int mersengerFunctionCount(float p) {
        return -std::log((1.0f - p) / 2.0f) / std::log(2.0f);
    }
};
```

