2. Bible Resource Bundle Parser

```rust
use regex::Regex;
use std::collections::HashMap;
use reqwest::Client;

pub fn parse_bundle(path: &str) -> Result<Bundle, ResourceError> {
    let text = std::fs::read_to_string(path)?;
    let re = Regex::new(r"\b[A-Z]{3}\b").unwrap();
    let book_names: Vec<&str> = re.find_iter(&text).map(|m| m.as_str()).collect();

    let valid_books = reqwest::blocking::get("http://example.com/valid-books")?
        .json::<HashMap<String, bool>>()?;

    let mut book_counts = HashMap::new();
    for book in &book_names {
        if valid_books.contains_key(book) {
            *book_counts.entry(book).or_insert(0) += 1;
        }
    }

    Ok(Bundle { books: book_counts })
}
```

