2. Caching Strategy:

```csharp
public class ConfigCache
{
    private readonly object _lock = new object();
    private Dictionary<string, DateTime> _cacheTimestamps;
    private Dictionary<string, object> _configCache;

    public void LoadFromConfigurationLoader(ConfigurationLoader loader)
    {
        lock (_lock)
        {
            if (_configCache == null || _cacheTimestamps.Any(x => DateTime.UtcNow - x.Value > TimeSpan.FromMinutes(5)))
            {
                // Re-load config data from loader when cache is stale or empty
                loader.LoadConfig();
                _configCache = new Dictionary<string, object>(loader._config);
                _cacheTimestamps = _configCache.ToDictionary(x => x.Key, x => DateTime.UtcNow);
            }
        }
    }

    public object GetConfigValue(string key)
    {
        lock (_lock)
        {
            if (_configCache.TryGetValue(key, out var value))
                return value;
        }

        return default!;
    }
}
