pub fn create_and_set_env_var(directory: &str) -> Result<(), Box<dyn std::error::Error> {
    let mut path = PathBuf::from(directory);
    if !path.exists() {
        create_dir_all(&path)?;
    }

    let directory_path = path.canonicalize().unwrap();

    // Check if environment variable is already set, use existing value if applicable
    if env::var_os("DIRECTORY_PATH").is_some() {
        let existing_path = env::var("DIRECTORY_PATH")?;
        if directory_path != existing_path {
