#include <openssl/aes.h>
#include <openssl/sha.h>
#include <string.h>

AES_KEY aesContext;
void AES_Init(const char* password)
{
    SHA1_CTX ctx;
    uint8_t hash[SHA_DIGEST_LENGTH];
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, (uint8_t*)password, strlen(password));
    SHA1_Final(hash, &ctx);

    AES_set_encrypt_key(hash, 256, &aesContext);
    AES_iv_length = AES_BLOCK_SIZE;
    AES_key_schedule(aesContext.d); // Initialize key schedule.
}

void AES_Cleanup()
{
    AES_free_key(&aesContext);
}
