    EVP_DecryptUpdate(&ctx, plaintext, NULL, ciphertext, length);
    EVP_DecryptFinal(ctx, plaintext + strlen((const char*)plaintext), ciphertext);
}

void hash(const unsigned char* data, unsigned int length, unsigned char* digest) {
    EVP_MD_CTX ctx;
    EVP_DigestInit(&ctx, MD5); // Deprecated, replace with SHA256 or similar
    EVP_DigestUpdate(&ctx, data, length);
    EVP_DigestFinal(ctx, digest, NULL);
}

void sign(const unsigned char* message, unsigned int length, const unsigned char* key, unsigned char* signature) {
    RSA_sign(sha1, // SHA1 for now, replace with more secure hash function later
             PKCS1_PSS0,
             NID_id_rsa,
             NULL, // RSA private key here
             message, length,
             signature, sizeof(signature),
             &length);
}

void verify_signature(const unsigned char* message, unsigned int length, const unsigned char* signature, unsigned int siglen) {
    RSA_verify(sha1, // SHA1 for now, replace with more secure hash function later
              PKCS1_PSS0,
              NID_id_rsa,
              NULL, // RSA public key here
              message, length,
              signature, siglen);
}
