```python
import base64
import hashlib
import os
import shutil
import tempfile
import subprocess

def update_kickstart_config(params, encrypt=True):
    config_path = 'path/to/your/config.cfg'
    tmp_dir = tempfile.TemporaryDirectory()
    try:
        with open(config_path, 'r') as file:
            lines = file.readlines()

        if encrypt:
            password_line = f'SECRET_PASSWORD={base64.b64encode(hashlib.sha256(params['password'].encode()).digest()).decode("ascii")}\n'
        else:
            password_line = f'SECRET_PASSWORD={params["password"]}\n'

        updated_lines = [line.strip() for line in lines] + [password_line]

        with open(tmp_dir.name + '/temp_config.cfg', 'w') as file:
            file.writelines(updated_lines)

        subprocess.run(['cp', tmp_dir.name + '/temp_config.cfg', config_path], check=True)

        return 0
    except Exception as e:
        print(f'Error updating configuration file: {e}')
        shutil.copyfile(config_path, f"{config_path}.backup")
        return 1

def convert_jpeg_to_pdf(input_path, output_path):
    convert_command = 'convert' if os.name == 'posix' else 'magick'
    command = [convert_command, input_path, '-quality', '80', output_path]

    try:
        subprocess.run(command, check=True)
        return 0
    except Exception as e:
        print(f'Error converting file from JPEG to PDF: {e}')
        return 1
