        this.maxSamples = maxSamples;
        this.sampleInterval = sampleInterval;
        this.bufferSize = bufferSize;
        this.batchSize = batchSize;
        this.reportPeriodicity = reportPeriodicity;
        dataLock = new ReentrantReadWriteLock();
        dataBuffer = new LinkedBlockingDeque<>(bufferSize);
    }

    // Methods for initializing, starting, and stopping the analyzer

    public void analyzeNetworkPerformance() {
        Runnable analysisTask = () -> {
            while (!Thread.currentThread().isInterrupted()) {
                Instant currentTime = Instant.now();
                NetworkData data = collectNetworkData();
                lockAndAddToBuffer(data);

                if (shouldAggregate(currentTime)) {
                    aggregateData();
