} NFAPI_CRC_INDICATION_PDU_T;

typedef struct HashTableNode {
    char key[32];
    int count;
    struct HashTableNode *next;
} HashTableNode;

typedef struct HashTable {
    unsigned long num_buckets;
    HashTableNode **table;
} HashTable;

// Regular expression pattern for Old Testament book names (without punctuation and special characters)
static regex_t book_regex;

// Function to create a new hash table node
HashTableNode* create_hash_node(char *key, int count) {
    HashTableNode *new_node = (HashTableNode *)malloc(sizeof(HashTableNode));
    strcpy(new_node->key, key);
    new_node->count = count;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a node into the hash table
void insert(HashTable *ht, HashTableNode *node) {
    unsigned long index = hash(node->key) % ht->num_buckets;
    node->next = ht->table[index];
    ht->table[index] = node;
}

// Function to find a node in the hash table by key
HashTableNode* search(HashTable *ht, const char *key) {
    unsigned long index = hash(key) % ht->num_buckets;
    HashTableNode *current = ht->table[index];

    while (current != NULL) {
        if (strcmp(current->key, key) == 0)
            return current;
        current = current->next;
    }

    return NULL;
}

// Function to hash a string key
unsigned long hash(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % ht->num_buckets;
}

