     ```
     function asyncReduce(arr, initialValue, callback) {
       arr.reduce((accumulator, currentValue, index, array) => {
         if (!callback) return accumulator;

         callback(accumulator, currentValue, index, array);

         // Once the callback returns a value, recurse with that as the new accumulator
         return new Promise((resolve) => {
           callback(accumulator, currentValue, index, array, (nextAccumulator) => resolve(nextAccumulator));
