async fn auth_service() -> Service<ServiceBuilder> {
    let client = Arc::new(Client::builder().build().unwrap());
    let mut builder = ServiceBuilder::new();
    builder.layer(ExponentialBackoff::new(10, 30.seconds()));
    builder.layer(HttpDebug::new());
    builder.layer(move |inner| async move {
        Box::pin(async move {
            let mut inner = inner?;
            let response = match refresh_token(client.clone(), inner.peer_addr().unwrap().to_string()).await {
                Ok(response) => response,
                Err(_) => {
                    // Implement retry logic here
                    inner.run_service((inner.request(), None)).await?;
                    return inner.run_service((inner.request(), None)).await;
                }
            };
            Ok(response)
        })
    })
}
