// Define the linked list node structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Global variables
Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for thread safety
int num_elements = 0;
int buffer_size = 10000;

// Function to initialize the dynamic linked list
void initList() {
    head = (Node*)malloc(sizeof(Node));
    if (!head) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    tail = head;
    head->next = NULL;
}

// Function to add an element to the dynamic linked list
void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Error: Out of memory\n");
        return;
    }

    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list_mutex);
    tail->next = newNode;
    tail = newNode;
    num_elements++;
    pthread_mutex_unlock(&list_mutex);
}

// Function to dequeue an element from the dynamic linked list, validating CRC flags and updating the external database.
void dequeue() {
    if (isEmpty()) return;

    Node* temp = head->next;
    NFAPI_CRC_INDICATION_PDU_T data = temp->data;

    // Perform CRC validation here using the external library
