    if (!isValid) {
        fprintf(stderr, "Error: Invalid CRC flag\n");
        return;
    }

    databaseUpdate(data); // Update the real-time database

    pthread_mutex_lock(&list_mutex);
    head->next = temp->next;
    if (num_elements == 1) {
        free(temp);
        head = NULL;
        tail = NULL;
    } else {
        num_elements--;
    }
    pthread_mutex_unlock(&list_mutex);
}

// Function to check if the dynamic linked list is empty
bool isEmpty() {
    return (head->next == NULL);
}

