#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <sqlite3.h>
#include <random>

struct Record {
    int value;
};

static std::mutex mtx; // Global mutex for thread safety
static sqlite3 *db = nullptr; // Global database connection
static sqlite3_stmt *insertStmt = nullptr; // Prepared statement for inserting records

void initDatabase() {
    int rc = sqlite3_open("records.db", &db);
    if (rc) {
        std::cerr << "Can't open database: " << sqlite3_errmsg(db) << std::endl;
        exit(1);
    }

    const char *sql = R"(CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, key INTEGER UNIQUE, value INTEGER));";
    rc = sqlite3_exec(db, sql, nullptr, nullptr, nullptr);
    if (rc != SQLITE_OK) {
        std::cerr << "SQL error: " << sqlite3_errmsg(db) << std::endl;
        exit(1);
    }

    const char *insertSql = "INSERT INTO records (key, value) VALUES (?, ?);";
    rc = sqlite3_prepare_v2(db, insertSql, -1, &insertStmt, nullptr);
    if (rc != SQLITE_OK) {
        std::cerr << "Failed to prepare statement: " << sqlite3_errmsg(db) << std::endl;
        exit(1);
    }
}

void cleanup() {
    if (insertStmt) sqlite3_finalize(insertStmt);
    if (db) sqlite3_close(db);
}

std::vector<Record> generateRecords(int N, int minValue, int maxValue) {
    std::vector<Record> records(N);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(minValue, maxValue);

    std::lock_guard<std::mutex> lock(mtx);

    for (size_t i = 0; i < records.size(); ++i) {
        records[i].value = dis(gen);
    }

    return records;
}

void insertRecord(const Record &record) {
    sqlite3_bind_int(insertStmt, 1, record.key);
    sqlite3_bind_int(insertStmt, 2, record.value);
    sqlite3_step(insertStmt); // Execute the INSERT statement
}

void insertRecordsSync(const std::vector<Record> &records) {
    for (const auto &record : records) {
        insertRecord(record);
    }
}

// Asynchronous insert function using thread pool
void insertRecordsAsync(const std::vector<Record> &records, int numThreads = std::thread::hardware_concurrency()) {
    std::vector<std::future<void>> futures;
    for (size_t i = 0; i < records.size(); ++i) {
        auto index = i;
        futures.push_back(std::async(std::launch::async, [index]() { insertRecord(records[index]); }));
        if (futures.size() == numThreads) {
            for (auto &future : futures) future.wait(); // Wait for all tasks to finish
            futures.clear();
        }
    }

    if (!futures.empty()) {
        for (auto &future : futures) future.wait(); // Wait for any remaining tasks to finish
    }
}

// Main function to execute the task
int main(int argc, char **argv) {
    if (argc != 7) {
        std::cerr << "Usage: " << argv[0] << " N minValue maxValue offsetSize keySize numThreads" << std::endl;
        return 1;
    }

    int N = std::stoi(argv[1]);
    int minValue = std::stoi(argv[2]);
    int maxValue = std::stoi(argv[3]);
    int offsetSize = std::stoi(argv[4]);
    int keySize = std::stoi(argv[5]);
    int numThreads = std::stoi(argv[6]);

    // Initialize the database and prepare the insert statement
    initDatabase();

    // Generate the records to be inserted
    auto records = generateRecords(N, minValue, maxValue);

    // Resize the input arrays for offsets and keys
    std::vector<int> offsets(N);
    std::vector<int> keys(N);

    for (size_t i = 0; i < N; ++i) {
        offsets[i] = i * offsetSize;
        keys[i] = records[i].key + i * keySize;
    }

