    private static class ListCache<K, V> {
        private final Map<K, V> cache;
        private final long expirationIntervalMillis;
        private final AtomicLong lastAccessTime = new AtomicLong(System.currentTimeMillis());

        public ListCache(long expirationIntervalMillis) {
            this.cache = new HashMap<>();
            this.expirationIntervalMillis = expirationIntervalMillis;
        }

        public void put(K key, V value) {
            cache.put(key, value);
            lastAccessTime.set(System.currentTimeMillis());
        }

        public Map<K, V> getAll() {
            return cache;
        }

        public void putAll(Map<? extends K, ? extends V> map) {
            map.forEach((key, value) -> put(key, value));
        }

        public void removeExpiredItems() {
            long currentTime = System.currentTimeMillis();
            cache.entrySet().removeIf(entry -> (currentTime - lastAccessTime.get()) > expirationIntervalMillis);
        }
    }
