```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.time.LocalDateTime;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Set;
import java.util.stream.Stream;

public class ConfigurationManager {

    private static final String MOST_STATE_FILE = "MostState";
    private static final String OLD_CONFIG_FILE = "OldConfig";

    private final Map<String, Configuration> configurations = new LinkedHashMap<>();

    public Map<String, Configuration> loadConfigurations(List<String> directoryPaths) {
        setUpConcurrentAccess();

        Set<Path> visitedDirectories = new HashSet<>();

        AtomicInteger mostRecentVersion = new AtomicInteger(0);

        Stream.of(directoryPaths)
                .filter(path -> !visitedDirectories.contains(Paths.get(path)))
                .forEach(this::traverseDirectoryAndLoadConfigurations);

        return Collections.unmodifiableMap(configurations);
    }

    private void traverseDirectoryAndLoadConfigurations(String directoryPath) {
        visitedDirectories.add(Paths.get(directoryPath));

        try (Stream<Path> files = Files.walk(Paths.get(directoryPath))) {
            files.filter(Files::isRegularFile)
                    .map(this::getConfigurationFile)
                    .sorted(Comparator.comparing(file -> getLastModifiedTime(file)))
                    .forEach(configurationFile -> loadConfigurationFromFile(configurationFile, mostRecentVersion));
        } catch (IOException e) {
            System.err.println("Error while reading directory: " + directoryPath);
            e.printStackTrace();
        }
    }

    private Path getConfigurationFile(Path file) {
        return file.toFile().getName().equalsIgnoreCase(MOST_STATE_FILE) ? file : null;
    }

    private LocalDateTime getLastModifiedTime(Path path) throws IOException {
        return Files.getLastModifiedTime(path);
    }

    private void loadConfigurationFromFile(Path configurationFile, AtomicInteger mostRecentVersion) throws IOException, ClassNotFoundException {
        try (ObjectInputStream objectInputStream = new ObjectInputStream(new FileInputStream(configurationFile.toFile()))) {
            Configuration config;
            if (configurationFile.getFileName().toString().equalsIgnoreCase(MOST_STATE_FILE)) {
                config = (Configuration) objectInputStream.readObject();
            } else { // Legacy configuration
                LocalDateTime lastModifiedTime = getLastModifiedTime(configurationFile);
                OldConfig oldConfig = new OldConfig();
                Files.copy(configurationFile, oldConfig.getTmpFile());
                oldConfig.loadFromTmpFile();
                config = oldConfig;
            }

            synchronized (configurations) {
                Configuration currentConfiguration = configurations.get(config.getName());
                if ((currentConfiguration == null || mostRecentVersion.get() > currentConfiguration.getVersion()) &&
                        (config instanceof MostState || (!config.hasSameDataAs(currentConfiguration)))) {
                    config.setVersion(mostRecentVersion.incrementAndGet());
                    configurations.put(config.getName(), config);
                }
            }
        } catch (FileNotFoundException | ClassCastException e) {
            System.err.println("Skipping file: " + configurationFile);
        } catch (IOException e) {
            System.err.println("Error while reading file: " + configurationFile);
            e.printStackTrace();
        }
    }

    private void setUpConcurrentAccess() {
        synchronized (configurations) {
            if (configurations.isEmpty()) {
                configurations.put(Configuration.DEFAULT_NAME, new MostState());
            }
        }
    }
}

class Configuration {

    public static final String DEFAULT_NAME = "default";

    protected String name;
    protected int version;

    protected Configuration() {
        this(DEFAULT_NAME);
    }

    protected Configuration(String name) {
        this.name = name;
        this.version = 0;
    }

    public void setName(String name) {
        if (!this.name.equalsIgnoreCase(name)) {
            throw new IllegalStateException("Cannot change the name of an existing configuration.");
        }
        this.name = name;
    }

    public String getName() {
        return this.name;
    }

    public void setVersion(int version) {
        if (this.version != 0) {
            throw new IllegalStateException("Cannot change the version of an existing configuration.");
        }
        this.version = version;
    }

    public int getVersion() {
        return this.version;
    }

    protected abstract void loadFromTmpFile();

    protected boolean hasSameDataAs(Configuration other) {
        throw new NoSuchElementException("This method must be overridden.");
    }
}

