3. **Java Function for Disjoint Pairs**

```java
import java.util.*;
import java.util.stream.Stream;

public class DisjointPairs {
    private static int[] parent;
    private static int[] rank;

    public static long countDisjointPairs(int[] arr) {
        int n = arr.length;
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 1;
        }

        long count = 0;
        Map<Integer, Long> pairs = new HashMap<>();

        Stream.iterate(0, i -> i + 1)
            .limit(n)
            .forEach(root -> {
                int rootId = findSet(root);
                Arrays.stream(arr).filter(val -> findSet(val) != rootId)
                    .forEach(val -> {
                        int valId = findSet(val);
                        long currentPairCount = pairs.getOrDefault(rootId, 0L) + 1;
                        long newPairCount = pairs.merge(valId, currentPairCount, (a, b) -> a + b - 2 * currentPairCount);
                        count += newPairCount / 2;
                        System.out.printf("Checking pair (%d, %d) takes %d ms\n", root, val, TimeUnit.MILLISECONDS.convert(System.currentTimeMillis() - startTime, TimeUnit.MICROSECOND));
                    });
            });

        return count;
    }

    private static int findSet(int x) {
        if (parent[x] != x) parent[x] = findSet(parent[x]);
        return parent[x];
    }
}
```
This function takes an integer array as input, finds disjoint pairs using a Union-Find data structure, and prints the time taken to check each pair.']

