[' C++:

```cpp
#include <iostream>
#include <forward_list>
#include <thread>
#include <mutex>

std::mutex mtx;

void modifyForwardList(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2, const std::string& operation) {
    auto it = list.begin();
    bool found = false;

    std::unique_lock<std::mutex> lock(mtx);
    for (; it != list.end() && !found; ++it) {
        if (*it == str1) {
            found = true;
            if (operation == "insert") {
                if (it != list.begin()) {
                    auto prev = it--;
                    prev->insert_after(prev, str2);
                } else {
                    list.insert_after(it, str2);
                }
            } else if (operation == "append") {
                it->insert_after(it, str2);
            }
        }
    }

    if (!found) {
        lock.unlock(); // Unlock the mutex as we won't be modifying the list anymore
        list.push_back(str2);
    }
}

// Main function to demonstrate concurrent access handling
int main() {
    std::forward_list<std::string> myList = {"apple", "banana", "cherry"};
    modifyForwardList(myList, "banana", "dragonfruit", "insert");
    modifyForwardList(myList, "orange", "kiwi", "append");

    // Simulate concurrent access (multiple threads) and demonstrate thread safety
    std::vector<std::thread> threads;
    for (size_t i = 0; i < 10; ++i) {
        threads.emplace_back(modifyForwardList, std::ref(myList), "orange", "grapefruit", "append");
    }

    for (auto& thread : threads) {
        thread.join();
    }

    for (const auto& str : myList) {
        std::cout << str << '\n';
    }
}
```

