struct MemoryPool {
    void* memory;
    size_t capacity;
    size_t used;
};

void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    if (pool->used + size <= pool->capacity) {
        void* result = pool->memory + pool->used;
        pool->used += size;
        return result;
    }
    return NULL;
}

void mempool_free(struct MemoryPool* pool, void* ptr) {
    if (ptr >= pool->memory && ptr < pool->memory + pool->capacity) {
        pool->used--;
    }
}

void mempool_init(struct MemoryPool* pool, size_t capacity) {
    pool->memory = malloc(capacity);
    pool->capacity = capacity;
    pool->used = 0;
}

NFAPI_CRC_INDICATION_PDU_T* generate_element() {
